(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-791":{scenario:{company:"Khách sạn Lam Ngọc Grand",supervisor:{name:"Vương Thanh Tùng",role:{vi:"Giám đốc Bộ phận Tiền sảnh",en:"Front Office Manager"}},ref_code:"FO-2418",title:{vi:"Đúng mã giá. Đúng hóa đơn. Đúng chuẩn 5 sao.",en:"Right rate code. Right invoice. Five-star standard."},brief:{vi:"Khách lưu trú 3 đêm thuộc một công ty có hợp đồng giá năm với khách sạn, giá hợp đồng 2.800.000 đồng/đêm, chưa gồm phí phục vụ và thuế. Bản nháp folio FO-2418 đang áp giá bán linh hoạt trong ngày. Kiểm tra hồ sơ khách và hợp đồng, sửa mã giá và tổng tiền phòng thanh toán (phí phục vụ 5%, thuế GTGT mô phỏng 10%), rồi lập báo cáo có căn cứ.",en:"A guest staying 3 nights belongs to a company with an annual rate agreement at 2,800,000 VND per night, excluding service charge and tax. Draft folio FO-2418 applies the flexible daily rate. Check the guest profile and the agreement, correct the rate code and the total room charges payable (service charge 5%, training VAT 10%), then write an evidence-based report."},reference_title:{vi:"Hồ sơ khách & hợp đồng giá năm đã duyệt · FO-2418",en:"Approved guest profile & rate agreement · FO-2418"},fields:[{id:"RATE_CODE",label:{vi:"Mã giá áp dụng",en:"Applied rate code"},initial:"BAR",expected:"CORP-LTA",choices:["BAR","CORP-LTA","RACK"],reference:"Hồ sơ khách và hợp đồng giá năm",hint:{vi:"Hồ sơ khách đã liên kết công ty có hợp đồng giá năm, mã giá phải theo hợp đồng chứ không theo giá bán trong ngày.",en:"The guest profile is linked to a company with an annual agreement, so the rate follows the contract, not the daily price."}},{id:"FOLIO_TOTAL",label:{vi:"Tổng tiền phòng thanh toán (VND)",en:"Room charges payable (VND)"},initial:"9660000",expected:"9702000",reference:"Bảng tính folio đã duyệt",ref_value:{vi:"Giá hợp đồng 2.800.000 đồng/đêm x 3 đêm; phí phục vụ 5%; thuế GTGT 10% (mô phỏng)",en:"Contract rate 2,800,000 VND per night x 3 nights; service charge 5%; VAT 10% (training)"},hint:{vi:"Thuế GTGT tính trên giá đã cộng phí phục vụ, không cộng gộp hai tỷ lệ thành một.",en:"VAT is charged on the price including service charge; do not simply add the two rates together."}}],sop32:{vi:"Tổng tiền phòng = giá phòng x số đêm x (1 + phí phục vụ 5%) x (1 + thuế GTGT 10%); thuế GTGT tính trên giá đã gồm phí phục vụ (tỷ lệ mô phỏng).",en:"Room total = room rate x nights x (1 + 5% service charge) x (1 + 10% VAT); VAT is charged on the price including service charge (training rates)."},context:{label:"PMS / FO-2418",metrics:[{label:{vi:"Giá hợp đồng",en:"Contract rate"},value:"2,800,000 VND"},{label:{vi:"Số đêm",en:"Nights"},value:"3"},{label:{vi:"Phí phục vụ + thuế",en:"Service charge + VAT"},value:"5% + 10%"}]},crisis:{vi:"Khách đề nghị xuất hóa đơn GTGT 12.000.000 đồng thay vì số thực để thanh toán với công ty, phần chênh lệch hoàn tiền mặt: “Khách sạn khác vẫn làm, không thì tôi chuyển nơi khác.” Quản lý trực bảo cứ chiều khách.",en:"The guest asks for a VAT invoice of 12,000,000 VND instead of the real amount to claim from the company, with the difference refunded in cash: “Other hotels do it, or I'll move.” The duty manager says to go along."},options:{safe:{vi:"Từ chối xuất hóa đơn sai thực tế, giải thích lịch sự, báo Giám đốc Tiền sảnh và kế toán, đề xuất hóa đơn đúng số tiền kèm bảng kê chi tiết dịch vụ đã dùng.",en:"Decline to issue an untrue invoice, explain politely, inform the Front Office Manager and accounting, and offer a correct invoice with a detailed statement of services."},shortcut:{vi:"Xuất hóa đơn 12.000.000 đồng theo yêu cầu và hoàn chênh lệch bằng tiền mặt để giữ khách.",en:"Issue the 12,000,000 VND invoice as asked and refund the difference in cash to keep the guest."},wait:{vi:"Hẹn khách để mai trả lời, không báo cho ai và để ca sau tự xử lý.",en:"Tell the guest you will answer tomorrow, inform no one and leave it to the next shift."}},questions:{vi:["Vì sao bạn đổi mã giá trên folio? Hồ sơ nào chứng minh khách thuộc hợp đồng công ty?","Trình bày cách tính tổng tiền phòng có phí phục vụ và thuế, và cách xử lý yêu cầu xuất hóa đơn không đúng thực tế."],en:["Why did you change the rate code on the folio? Which record proves the guest is under the company agreement?","Explain how you calculated the room total with service charge and tax, and how you handle a request for an untrue invoice."]},hints:{vi:["Mở hồ sơ khách trên PMS và kiểm tra trường công ty liên kết trước khi chọn mã giá.","Theo SOP mục 3.2: cộng phí phục vụ trước, sau đó mới tính thuế GTGT trên số đã cộng.","Đọc lại SOP mục 4.2: hóa đơn phải đúng nội dung và số tiền thực tế, mọi yêu cầu khác phải báo cáo."],en:["Open the guest profile in the PMS and check the linked company field before choosing a rate code.","Per SOP 3.2: add the service charge first, then apply VAT on the resulting amount.","Re-read SOP 4.2: invoices must show the real content and amount; any other request must be escalated."]}},learning:{summary:{vi:"Giám sát tiền sảnh khách sạn 5 sao điều hành ca lễ tân: đón tiếp, nhận và trả phòng, phân phòng, quản lý folio, chăm sóc khách VIP và xử lý phàn nàn. Người giám sát bảo đảm giá, hóa đơn và thông tin khách chính xác, khai báo lưu trú đúng quy định và phối hợp nhịp nhàng với buồng phòng, đặt phòng, nhà hàng, an ninh. Nghề đòi hỏi phong thái chuyên nghiệp, ngoại ngữ tốt, kỹ năng hệ thống và sự liêm chính trước áp lực của khách.",en:"A five-star front office supervisor runs the reception shift: welcoming guests, check-in and check-out, room assignment, folio control, VIP care and complaint handling. The supervisor keeps rates, invoices and guest data accurate, files guest registrations as required and coordinates with housekeeping, reservations, restaurants and security. The role needs professional presence, strong languages, system skills and integrity under guest pressure."},responsibilities:{vi:["Phân công và giám sát ca lễ tân, kiểm tra tiêu chuẩn đón tiếp và ngoại hình nhân viên.","Kiểm soát giá, mã giá, folio và đối chiếu thanh toán trước khi khách trả phòng.","Phân phòng, chuẩn bị khách VIP, nâng hạng có thu và phối hợp trạng thái phòng với buồng phòng.","Thực hiện khai báo lưu trú cho khách và bảo mật thông tin cá nhân theo quy định.","Xử lý phàn nàn, sự cố an ninh và lập báo cáo bàn giao ca."],en:["Schedule and supervise reception shifts and check service standards and grooming.","Control rates, rate codes and folios and reconcile payments before check-out.","Assign rooms, prepare VIP arrivals, upsell and align room status with housekeeping.","File guest registrations with the authorities and protect personal data as required.","Handle complaints and security incidents and write the shift handover report."]},competencies:[{name:{vi:"Kiểm soát giá & folio",en:"Rate & folio control"},desc:{vi:"Áp đúng mã giá theo hợp đồng, tính đúng phí phục vụ, thuế và đối chiếu thanh toán.",en:"Apply the contracted rate code, compute service charge and tax correctly and reconcile payments."}},{name:{vi:"Trải nghiệm khách",en:"Guest experience"},desc:{vi:"Đọc nhu cầu khách, cá nhân hóa dịch vụ và biến phàn nàn thành cơ hội giữ khách.",en:"Read guest needs, personalise service and turn complaints into loyalty."}},{name:{vi:"Điều phối liên bộ phận",en:"Cross-department coordination"},desc:{vi:"Phối hợp buồng phòng, kỹ thuật, nhà hàng để phòng sẵn sàng đúng giờ và đúng yêu cầu.",en:"Work with housekeeping, engineering and restaurants so rooms are ready on time and as requested."}},{name:{vi:"Tuân thủ & bảo mật",en:"Compliance & privacy"},desc:{vi:"Khai báo lưu trú đúng hạn, bảo vệ dữ liệu khách và lập hóa đơn đúng thực tế.",en:"File registrations on time, protect guest data and issue invoices that reflect reality."}},{name:{vi:"Lãnh đạo ca",en:"Shift leadership"},desc:{vi:"Phân công hợp lý, kèm cặp nhân viên mới và giữ bình tĩnh trong giờ cao điểm.",en:"Plan staff well, coach new hires and stay calm at peak times."}}],knowledge:{vi:["Luật Du lịch số 09/2017/QH14 và TCVN 4391:2015 về xếp hạng khách sạn.","Quy định về thông báo lưu trú theo Luật Cư trú 2020 và khai báo tạm trú cho người nước ngoài.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ: hóa đơn phải đúng nội dung và số tiền thực tế.","Pháp luật hiện hành về bảo vệ dữ liệu cá nhân: thu thập, sử dụng thông tin khách đúng mục đích.","Hệ thống báo cáo thống nhất ngành khách sạn (USALI), mã trạng thái phòng và quy trình kiểm toán đêm."],en:["Tourism Law No. 09/2017/QH14 and TCVN 4391:2015 on hotel classification.","Guest stay notification under the 2020 Residence Law and temporary residence declaration for foreigners.","Decree 123/2020/ND-CP on invoices: an invoice must show the real content and amount.","Current personal data protection law: collect and use guest data only for stated purposes.","Uniform System of Accounts for the Lodging Industry (USALI), room status codes and night audit."]},tools:["Phần mềm quản lý khách sạn (PMS)","Hệ thống mã hóa khóa từ","Máy thanh toán thẻ (POS)","Cổng khai báo lưu trú trực tuyến","Hệ thống hóa đơn điện tử"],kpis:{vi:["Thời gian nhận phòng trung bình mỗi khách.","Điểm hài lòng của khách và điểm đánh giá trực tuyến về lễ tân.","Tỷ lệ folio phải điều chỉnh sau khi khách trả phòng (mục tiêu dưới 1%).","Doanh thu nâng hạng phòng có thu mỗi ca."],en:["Average check-in time per guest.","Guest satisfaction and online review scores for reception.","Share of folios corrected after check-out (target below 1%).","Paid room upgrade revenue per shift."]},day:[{time:"06:45",vi:"Nhận ca, đọc nhật ký bàn giao, danh sách khách VIP và phòng trả trong ngày.",en:"Take over the shift, read the handover log, VIP list and today's departures."},{time:"08:00",vi:"Điều phối giờ cao điểm trả phòng, kiểm tra folio và hóa đơn trước khi in.",en:"Run the peak check-out period and check folios and invoices before printing."},{time:"11:00",vi:"Phân phòng cho khách đến, phối hợp buồng phòng ưu tiên phòng khách VIP.",en:"Assign rooms for arrivals and ask housekeeping to prioritise VIP rooms."},{time:"14:00",vi:"Đón đoàn và khách VIP, xử lý yêu cầu đổi phòng và nâng hạng có thu.",en:"Welcome groups and VIPs and handle room changes and paid upgrades."},{time:"17:30",vi:"Hoàn tất khai báo lưu trú, kiểm tra quỹ tiền và lập báo cáo bàn giao ca.",en:"Complete guest registrations, check the cash float and write the handover report."}],mistakes:{vi:["Không liên kết hồ sơ khách với công ty có hợp đồng nên áp sai mã giá.","Cộng gộp phí phục vụ và thuế thành một tỷ lệ thay vì tính thuế trên giá đã có phí phục vụ.","Tiết lộ số phòng hoặc cấp thẻ phòng cho người tự xưng là người thân mà không xác minh."],en:["Not linking the guest profile to the contracted company, so the wrong rate code is used.","Adding service charge and tax as one rate instead of taxing the price including service charge.","Disclosing a room number or issuing a key to a self-declared relative without verification."]},career:[{vi:"Nhân viên lễ tân",en:"Front desk agent"},{vi:"Trưởng ca lễ tân",en:"Front desk shift leader"},{vi:"Giám sát tiền sảnh",en:"Front office supervisor"},{vi:"Giám đốc Bộ phận Tiền sảnh hoặc Giám đốc Khối Phòng",en:"Front office manager or rooms division manager"}],glossary:[{term:"BAR",vi:"Giá bán tốt nhất trong ngày, thay đổi theo nhu cầu, dùng cho khách lẻ không có hợp đồng.",en:"Best available rate of the day, changing with demand, used for guests without a contract."},{term:"Folio",vi:"Tài khoản chi tiết của khách ghi nhận tiền phòng, dịch vụ, thanh toán trong thời gian lưu trú.",en:"Guest account recording room charges, services and payments during the stay."},{term:"Night audit",vi:"Kiểm toán đêm: chốt doanh thu, đối chiếu folio và trạng thái phòng cuối ngày kinh doanh.",en:"End-of-day closing of revenue, folio reconciliation and room status check."},{term:"Upselling",vi:"Bán nâng hạng phòng hoặc dịch vụ cao hơn có thu thêm, phù hợp nhu cầu khách.",en:"Selling a higher room category or service at extra charge to fit guest needs."},{term:"Guaranteed reservation",vi:"Đặt phòng được bảo đảm bằng thẻ hoặc đặt cọc, khách sạn giữ phòng kể cả khi khách đến muộn.",en:"Booking secured by card or deposit, held even if the guest arrives late."}],quiz:[{q:{vi:"Giá phòng 2.000.000 đồng/đêm chưa gồm phí phục vụ 5% và thuế GTGT 10% (mô phỏng), khách ở 2 đêm. Tổng tiền phòng là bao nhiêu?",en:"The room rate is 2,000,000 VND per night excluding 5% service charge and 10% VAT (training rates), for 2 nights. What is the room total?"},options:{vi:["4.600.000 đồng","4.400.000 đồng","4.620.000 đồng","4.200.000 đồng"],en:["4,600,000 VND","4,400,000 VND","4,620,000 VND","4,200,000 VND"]},answer:2,explain:{vi:"4.000.000 x 1,05 = 4.200.000; cộng thuế 10% trên số đó được 4.620.000 đồng.",en:"4,000,000 x 1.05 = 4,200,000; adding 10% VAT on that gives 4,620,000 VND."}},{q:{vi:"Một người gọi điện tự xưng là vợ của khách và hỏi số phòng. Bạn làm gì?",en:"A caller says she is a guest's wife and asks for the room number. What do you do?"},options:{vi:["Không tiết lộ, nối máy vào phòng hoặc nhắn khách để khách tự quyết định","Đọc số phòng vì là người thân","Hỏi ngày sinh của khách rồi cho số phòng","Đề nghị người gọi đến quầy lấy thẻ phòng"],en:["Do not disclose; connect the call or message the guest so the guest decides","Give the number because she is family","Ask for the guest's birth date, then give the number","Invite the caller to collect a key at the desk"]},answer:0,explain:{vi:"Số phòng là thông tin bảo mật; chỉ khách đăng ký mới quyết định có tiếp người gọi hay không.",en:"The room number is confidential; only the registered guest decides whether to receive the caller."}},{q:{vi:"Mã giá BAR trong khách sạn có nghĩa là gì?",en:"What does the BAR rate code mean in a hotel?"},options:{vi:["Giá niêm yết cao nhất","Giá cho đoàn khách","Giá nội bộ cho nhân viên","Giá bán tốt nhất trong ngày cho khách lẻ"],en:["Highest published rate","Group rate","Staff rate","Best available daily rate for individual guests"]},answer:3,explain:{vi:"BAR là giá bán tốt nhất trong ngày, thay đổi theo nhu cầu, khác với giá hợp đồng công ty và giá niêm yết.",en:"BAR is the best available daily rate, driven by demand, unlike corporate contract rates and rack rates."}},{q:{vi:"Khách thân thiết đề nghị xuất hóa đơn cao hơn số thực để thanh toán với công ty. Cách xử lý đúng là gì?",en:"A loyal guest asks for an invoice above the real amount to claim from the company. What is the right response?"},options:{vi:["Chiều khách để giữ quan hệ","Từ chối lịch sự, xuất hóa đơn đúng thực tế và báo quản lý","Xuất hóa đơn rồi hủy sau","Đề nghị khách tự sửa hóa đơn"],en:["Go along to keep the relationship","Decline politely, issue a true invoice and inform the manager","Issue it and cancel it later","Let the guest edit the invoice"]},answer:1,explain:{vi:"Lập hóa đơn không đúng thực tế là vi phạm pháp luật về hóa đơn; phải xuất đúng và báo cáo yêu cầu bất thường.",en:"An untrue invoice breaks invoicing law; issue a true one and escalate the unusual request."}}],tools_en:["Hotel property management system (PMS)","Key card encoding system","Card payment terminal (POS)","Online guest residence declaration portal","E-invoicing system"]}}})})(window.KKR);
